  }
  if (mrb_singleton_class(mrb_class(self))) {
    mrb_raise(mrb, E_TYPE_ERROR, "can't clone singleton class");
  }

  clone = mrb_obj_dup(mrb, self);
  mrb_iv_copy(mrb, mrb_obj_value(mrb_data_object_clone(mrb, mrb_obj_ptr(clone))), mrb_obj_value(mrb_data_object_clone(mrb, mrb_obj_ptr(self))));
  mrb_set_flag(mrb, mrb_obj_ptr(clone), mrb_obj_ptr(self));
  mrb_set_singleton_class(mrb, mrb_obj_ptr(clone), mrb_class_clone(mrb, mrb_class(self)));

  return clone;
