mrb_value
clone_mrb_object(mrb_state *mrb, mrb_value self)
{
  mrb_value result;
  struct RObject *original, *clone;

  if (mrb_immediate_p(self)) {
    mrb_raise(mrb, E_TYPE_ERROR, "immediate value cannot be cloned");
  }

  if (mrb_obj_singleton_p(self)) {
    mrb_raise(mrb, E_TYPE_ERROR, "singleton class cannot be cloned");
  }

  original = mrb_obj_ptr(self);
  clone = mrb_obj_alloc(mrb, mrb_obj_class(self), mrb_obj_iv_get(mrb, self, mrb_intern_lit(mrb, "klass")));

  result = mrb_obj_value((struct RObject *)clone);

  mrb_obj_singleton_clone(mrb, result, self);

  mrb_iv_copy(mrb, result, self);

  if (mrb_obj_frozen_p(self)) {
    mrb_obj_freeze(mrb, result);
  }

  return result;
}

