    mrb_obj_freeze(mrb, clone);
  }

  return clone;
}

mrb_value
mrb_clone(mrb_state *mrb, mrb_value self)
{
  mrb_value clone;

  if (mrb_immediate_p(self)) {
    mrb_raise(mrb, E_TYPE_ERROR, "can't clone immediate value");
  }
  if (mrb_singleton_class(mrb_class(self))) {
    mrb_raise(mrb, E_TYPE_ERROR, "can't clone singleton class");
  }

  clone = mrb_obj_new(mrb, mrb_class(self), 0, NULL);
  mrb_data_object_dup(mrb, mrb_obj_ptr(clone), mrb_obj_ptr(self));
  mrb_obj_iv_copy(mrb, mrb_obj_ptr(clone), mrb_obj_ptr(self));
  if (mrb_obj_singleton_class(mrb_obj_ptr(self))) {
    mrb_value c = mrb_obj_value(mrb_obj_singleton_class(mrb_obj_ptr(self)));
    mrb_value sc = mrb_obj_value(mrb_make_singleton_class(mrb, mrb_obj_ptr(clone)));
    mrb_obj_iv_copy(mrb, mrb_obj_ptr(sc), mrb_obj_ptr(c));
  }
  if (mrb_obj_frozen_p(mrb_obj_ptr(self))) {
    mrb_obj_freeze(mrb, mrb_obj_ptr(clone));
  }

  return clone;
}

mrb_value
mrb_clone(mrb_state *mrb, mrb_value self)
{
  mrb_value clone;
  mrb_value tmp;

  if (mrb_immediate_p(self)) {
    mrb_raise(mrb, E_TYPE_ERROR, "can't clone immediate value");
  }

  if (mrb_singleton_class_p(mrb, self)) {
    mrb_raise(mrb, E_TYPE_ERROR, "can't clone singleton class");
  }

  clone = mrb_obj_clone(mrb, self);
  mrb_iv_copy(mrb, clone, self);
  mrb_cptr_assign(mrb, clone, mrb_cptr(self));

  if (mrb_obj_is_frozen(self)) {
    mrb_obj_freeze(mrb, clone);
  }

  return clone;
}
